	tool := v.opts.Helm
	for _, chart := range charts {
		if !available(tool) {
			v.report.Unrendered = append(v.report.Unrendered, chart)
			continue
		}
		lint := helmLint(ctx, v.target, chart, tool)
		v.report.Findings = append(v.report.Findings, lint...)

		cmd := helmArgs(v.target, chart, tool, "template")
		log.Printf("Running: %s", cmd)
		rendered, err := runner.Run(ctx, cmd, nil)
		if err != nil {
			if ctx.Err() != nil {
				return ctx.Err()
			}
			// helm lint renders the chart too, so a chart that does not
			// render has usually been reported by it already, with more to
			// say. The render failure is the fallback, not a second copy.
			if !hasError(lint) {
				v.report.Findings = append(v.report.Findings,
					renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", err))
			}
			continue
		}
		origins := helmOrigins(rendered, chart)
		err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
			if file, ok := origins[kind+"/"+name]; ok {
				return file
			}
			return chart
		})
		if err != nil {
			return fmt.Errorf("chart %s: %w", chart, err)
		}
	}
	return nil
}"},{"rank":5,"score":22.8103,"file_path":"internal/nexusbench/repoapi.go","start_line":159,"end_line":176,"focus_line":167,"snippet_start_line":167,"snippet_end_line":176,"symbol_start_line":167,"symbol_end_line":176,"language":"Go","kind":"function","symbol_id":"local/nexus-recorded-fixtures-devdesk-511:Go:internal/nexusbench/repoapi.go:function:requireLoopbackBase","symbol_name":"requireLoopbackBase","qualified_name":"requireLoopbackBase","signature":"func requireLoopbackBase(baseURL string) error","signals":["path","body","symbol-name","graph:callers","complete-symbol"],"snippet":"func requireLoopbackBase(baseURL string) error {
