46	// Error returns "<Op>: HTTP <status> <text>".
47	func (e *APIError) Error() string {
48		return strings.TrimSpace(fmt.Sprintf("%s: HTTP %d %s", e.Op, e.Status, http.StatusText(e.Status)))
49	}
