			path := e.pending("z-bad--admin", recDockerHost, "/v2/_catalog")
			if tt.refused {
				e.refuse("z-bad--admin")
				return
			}
			if _, err := e.record(); err != nil {
				t.Fatalf("RecordFixtures: %v", err)
			}
			requireRecorded(t, path, "2026-11-18")
		})
