func recTargetOK(target string) bool {
	p, q, _ := strings.Cut(target, "?")
	if strings.ContainsAny(target, "%") || strings.Contains(p, "..") || strings.Contains(p, "/manifests/") || strings.Contains(p, "/blobs/") {
