const recCheck = "fix the cause, then run `mise run nexus-bench:record`"

var (
	reV2   = regexp.MustCompile(`^/v2/(_catalog|[a-z0-9._/-]+/tags/list)?$`)
	reRepo = regexp.MustCompile(`^/repository/[^/]+/v2/_catalog$`)
	reREST = regexp.MustCompile(`^/service/rest/v1/repositories(/.*)?$`)
)

func recTargetOK(target string) bool {
	p, q, _ := strings.Cut(target, "?")
	if strings.ContainsAny(target, "%") || strings.Contains(p, "..") || strings.Contains(p, "/manifests/") || strings.Contains(p, "/blobs/") {
		return false
	}
	if q != "" {
		vals, err := url.ParseQuery(q)
		if err != nil {
			return false
		}
		for k := range vals {
			if k != "n" && k != "last" {
				return false
			}
		}
	}
	return reV2.MatchString(p) || reRepo.MatchString(p) || reREST.MatchString(p)
}

type recPlan struct {
	f    nexusfixture.Fixture
	file string
	data []byte
	user string
	pass string
}

func RecordFixtures(ctx context.Context, o RecordOptions) (RecordReport, error) {
	var rep RecordReport
	if err := ctx.Err(); err != nil {
		return rep, &BenchError{Cause: "cancelled", Check: recCheck, Err: err}
	}
	dir := o.Dir
	if dir == "" {
		d, err := nexusfixture.SourceDir()
		if err != nil {
			return rep, &BenchError{Cause: "no fixtures folder", Check: recCheck, Err: err}
		}
		dir = d
	}
	if info, err := os.Stat(dir); err != nil || !info.IsDir() {
		return rep, recErr(recCheck, "the fixtures folder %s is not there", dir)
	}
	// origins
	for host, base := range o.Origins {
		if err := requireLoopbackBase(base); err != nil {
			return rep, recErr(recCheck, "the origin of %s is not on the loopback", host)
		}
		h, p, err := net.SplitHostPort(host)
		port, _ := strconv.Atoi(p)
		ok := err == nil && slices.Contains(o.Descriptor.Hosts, h) && (port == o.Descriptor.REST.NodePort)
		for _, dc := range o.Descriptor.DockerConnectors {
			ok = ok || (err == nil && slices.Contains(o.Descriptor.Hosts, h) && port == dc.NodePort)
		}
		if !ok {
			return rep, recErr(recCheck, "%s is not a host:port of the bench descriptor", host)
		}
	}
	campaigns := o.Campaigns
	if len(campaigns) == 0 {
		entries, err := os.ReadDir(dir)
		if err != nil {
			return rep, recErr(recCheck, "cannot read %s", dir)
		}
		for _, e := range entries {
			if e.IsDir() {
				campaigns = append(campaigns, e.Name())
			}
		}
	}
	if o.Only != "" {
		if _, err := path.Match(o.Only, "x"); err != nil {
			return rep, recErr(recCheck, "the filter %q is not a glob", o.Only)
		}
	}
	var plans []recPlan
	exact := recTerms(o)
	for _, c := range campaigns {
		if c == "" || strings.ContainsAny(c, `/\`) || strings.Contains(c, "..") {
			return rep, recErr(recCheck, "campaign %q is not a campaign name", c)
		}
		cdir := filepath.Join(dir, c)
		entries, err := os.ReadDir(cdir)
		if err != nil {
			return rep, recErr(recCheck, "campaign %s is not in %s", c, dir)
		}
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), ".http") {
				continue
			}
			name := strings.TrimSuffix(e.Name(), ".http")
			if o.Only != "" {
				if m, _ := path.Match(o.Only, name); !m {
					continue
				}
			}
			file := filepath.Join(cdir, e.Name())
			data, err := os.ReadFile(file) //nolint:gosec // tmp
			if err != nil {
				return rep, recErr(recCheck, "cannot read fixture %s", name)
			}
			f, err := nexusfixture.Parse(c, e.Name(), data)
			if err != nil {
				return rep, &BenchError{Cause: "fixture " + name + " does not parse", Check: recCheck, Err: err}
			}
			label := c + "/" + name
			switch {
			case strings.HasPrefix(f.Meta.Record, "skip"):
				rep.Skipped = append(rep.Skipped, label+": "+f.Meta.Record)
				continue
			case len(f.Exchanges) != 1:
				rep.Skipped = append(rep.Skipped, label+": more than one exchange is not supported yet")
				continue
			}
			if leaks := nexusfixture.CheckLeaks(name, data, nil); len(leaks) != 0 && f.Meta.Record == nexusfixture.RecordPending {
				return rep, recErr(recCheck, "fixture %s: request refused by rule %s", name, leaks[0].Rule)
			}
			ex := f.Exchanges[0]
			if ex.Method != "GET" {
				return rep, recErr(recCheck, "fixture %s: method %s is not GET", name, ex.Method)
			}
			if !recTargetOK(ex.Target) {
				return rep, recErr(recCheck, "fixture %s: the target is not on the closed list", name)
			}
			if _, ok := o.Origins[ex.Host]; !ok {
				return rep, recErr(recCheck, "fixture %s: no origin for %s", name, ex.Host)
			}
			p := recPlan{f: f, file: file, data: data}
			switch f.Identity {
			case nexusfixture.Admin:
				p.user, p.pass = "admin", o.Secrets.AdminPassword
				if p.pass == "" {
					return rep, recErr(recCheck, "fixture %s: no admin credential", name)
				}
			case nexusfixture.Pull:
				p.user, p.pass = "bench-pull", o.Secrets.PullPassword
				if p.pass == "" {
					return rep, recErr(recCheck, "fixture %s: no pull credential", name)
				}
			}
			plans = append(plans, p)
		}
	}
	// dataset
	if len(plans) > 0 {
		if err := recDataset(ctx, o); err != nil {
			return rep, err
		}
	}
	type result struct {
		p    recPlan
		out  []byte
		same bool
	}
	var results []result
	for _, p := range plans {
		if err := ctx.Err(); err != nil {
			return rep, &BenchError{Cause: "cancelled", Check: recCheck, Err: err}
		}
		ex := p.f.Exchanges[0]
		c := newClient(o.Origins[ex.Host], p.user, p.pass)
		status, h, body, err := c.exchange(ctx, ex.Method, ex.Target, ex.RequestHeader)
		c.closeIdle()
		if err != nil {
			return rep, &BenchError{Cause: "fixture " + p.f.Name + ": no usable answer", Check: recCheck, Err: err}
		}
		want := "Nexus/" + o.Descriptor.NexusVersion + " (" + o.Descriptor.Edition + ")"
		if h.Get("Server") != want {
			return rep, recErr("run `mise run nexus-bench:up`, then the record again", "fixture %s: the bench is not the Nexus of the descriptor", p.f.Name)
		}
		raw := status2(status) + "\n"
		for k, v := range h {
			raw += k + ": " + strings.Join(v, ",") + "\n"
		}
		raw += string(body)
		for _, t := range recVariants(exact) {
			if strings.Contains(strings.ToLower(raw), strings.ToLower(t)) {
				return rep, recErr(recCheck, "fixture %s: rule exact-term", p.f.Name)
			}
		}
		if mt, _, _ := mime.ParseMediaType(h.Get("Content-Type")); strings.HasSuffix(mt, "json") && len(body) > 0 && !json.Valid(body) {
			return rep, recErr(recCheck, "fixture %s: the body is declared JSON and is not", p.f.Name)
		}
		red := nexusfixture.Redact(nexusfixture.RawExchange{Method: ex.Method, Target: ex.Target, Host: ex.Host, RequestHeader: ex.RequestHeader, Status: status, Header: h, Body: body})
		if red.Body != nil && red.Header.Get("Content-Length") != "" {
			red.Header.Set("Content-Length", strconv.Itoa(len(red.Body)))
		}
		nf := p.f
		nf.Exchanges = []nexusfixture.Exchange{red}
		same := false
		oldEx := p.f.Exchanges[0]
		if p.f.Meta.Record != nexusfixture.RecordPending && oldEx.Status == red.Status && bytes.Equal(oldEx.Body, red.Body) && oldEx.Stub == red.Stub && fmt.Sprint(oldEx.Header) == fmt.Sprint(red.Header) {
			same = true
		}
		nf.Meta.NexusVersion, nf.Meta.Edition = o.Descriptor.NexusVersion, o.Descriptor.Edition
		nf.Meta.Measured = o.Now().Format("2006-01-02")
		nf.Meta.RecordedBy = "nexus-bench record"
		nf.Meta.Record = ""
		out := nexusfixture.Format(nf)
		if _, err := nexusfixture.Parse(nf.Campaign, nf.Name+".http", out); err != nil {
			return rep, &BenchError{Cause: "fixture " + nf.Name + ": does not read back", Check: recCheck, Err: err}
		}
		if leaks := nexusfixture.CheckLeaks(nf.Name, out, exact); len(leaks) != 0 {
			return rep, recErr(recCheck, "fixture %s: rule %s", nf.Name, leaks[0].Rule)
		}
		results = append(results, result{p, out, same})
	}
	for _, r := range results {
		label := r.p.f.Campaign + "/" + r.p.f.Name
		if r.same {
			rep.Unchanged = append(rep.Unchanged, label)
			continue
		}
		if err := writeFileAtomic(r.p.file, r.out, 0o644, 0o755); err != nil {
			return rep, &BenchError{Cause: "write " + label, Check: recCheck, Err: err}
		}
		rep.Written = append(rep.Written, label)
	}
	sort.Strings(rep.Written)
	return rep, nil
}

func status2(s int) string { return strconv.Itoa(s) }

func recTerms(o RecordOptions) []string {
	t := []string{o.Secrets.AdminPassword, o.Secrets.PullPassword, recB64("admin", o.Secrets.AdminPassword), recB64("bench-pull", o.Secrets.PullPassword)}
	return append(t, o.DenyTerms...)
}
func recVariants(t []string) []string {
	var out []string
	for _, s := range t {
		if s != "" && s != recB64("admin", "") && s != recB64("bench-pull", "") {
			out = append(out, s)
		}
	}
	return out
}
func recB64(u, p string) string {
	if p == "" {
		return ""
	}
	return basicEnc(u + ":" + p)
}

func recDataset(ctx context.Context, o RecordOptions) error {
	d := o.Descriptor
	if len(d.Dataset) == 0 {
		return recErr(recCheck, "the descriptor lists no data set")
	}
	base := o.Origins[net.JoinHostPort(d.Hosts[0], strconv.Itoa(d.REST.NodePort))]
	if base == "" {
		return recErr(recCheck, "no origin for the REST port")
	}
	for _, repo := range []string{"docker-hosted", "docker-proxy"} {
		listed, err := ListImagesAnonymously(ctx, base, repo)
		if err != nil {
			return &BenchError{Cause: "cannot read the data set of " + repo, Check: recCheck, Err: err}
		}
		have := map[string]string{}
		for _, l := range listed {
			have[l.Name+":"+l.Tag] = l.Digest
		}
		diffs := 0
		for _, img := range d.Dataset {
			if !((repo == "docker-hosted" && img.Location == "docker-hosted") || (repo == "docker-proxy" && img.CachedInProxy)) {
				continue
			}
			k := img.Name + ":" + img.Tag
			dg, ok := have[k]
			delete(have, k)
			if ok && dg == "" {
				return recErr(recCheck, "the listing gives no digest")
			}
			if !ok || dg != img.Digest {
				diffs++
			}
		}
		if diffs+len(have) > 0 {
			return recErr("run `mise run nexus-bench:reset`", "the data set of %s differs from the descriptor", repo)
		}
	}
	return nil
}
